/**
 * Opening customer screens. Typed by hand: the generated route types don't list the customer area's tabs yet (they
 * are regenerated by the dev server).
 */
import { router, type Href } from "expo-router";

type CustomerPath = "/customer" | "/customer/appointments" | "/customer/messages" | "/customer/invoices" | "/customer/me" | "/customer/documents" | "/customer/password" | "/customer/add-business";

export function goCustomer(path: CustomerPath): void {
  router.navigate(path as Href);
}

/** Book an appointment, or move one (`reschedule`: its id). */
export function openBook(reschedule?: number): void {
  router.push((reschedule ? `/customer/book?reschedule=${reschedule}` : "/customer/book") as Href);
}
